const sharp = require('sharp');
const crypto = require('crypto');
const originalBuffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const hash = crypto.createHash('sha256').update(originalBuffer).digest('hex');
const metadata = await sharp(originalBuffer).metadata();
const originalWidth = metadata.width;
const originalHeight = metadata.height;
const resizedBuffer = await sharp(originalBuffer).resize({ width: 1568, height: 1568, fit: 'inside', withoutEnlargement: true }).jpeg({ quality: 85 }).toBuffer();
const resizedBinary = await this.helpers.prepareBinaryData(resizedBuffer, 'resized.jpg', 'image/jpeg');
const originalBinary = await this.helpers.prepareBinaryData(originalBuffer, 'original.jpg', 'image/jpeg');
const storagePath = $('Sub-workflow Input').item.json.storagePath;
const lastSlash = storagePath.lastIndexOf('/');
const storagePrefix = lastSlash === -1 ? '' : storagePath.slice(0, lastSlash);
return [{ json: { hash: hash, originalWidth: originalWidth, originalHeight: originalHeight, storagePrefix: storagePrefix }, binary: { data: resizedBinary, original: originalBinary } }];

const sourceBinary = $('Compute Hash & Resize').item.binary;
const items = $input.all();
for (const item of items) { item.binary = sourceBinary; }
return items;

const { z } = require('zod');
function parseBalancedFrom(text, start) {
  let depth = 0; let inString = false; let escape = false;
  for (let i = start; i < text.length; i++) {
    const ch = text[i];
    if (inString) { if (escape) escape = false; else if (ch === '\\') escape = true; else if (ch === '"') inString = false; continue; }
    if (ch === '"') inString = true;
    else if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (depth === 0) { try { return { value: JSON.parse(text.slice(start, i + 1)), end: i }; } catch (e) { return null; } } }
  }
  return null;
}
function extractJson(text) {
  const objects = [];
  let cursor = text.indexOf('{');
  while (cursor !== -1) {
    const parsed = parseBalancedFrom(text, cursor);
    if (parsed) { objects.push(parsed.value); cursor = text.indexOf('{', parsed.end + 1); }
    else { cursor = text.indexOf('{', cursor + 1); }
  }
  if (objects.length === 0) throw new Error('No JSON object found in skill output');
  return objects[objects.length - 1];
}
const confidence = z.enum(['high', 'medium', 'low']);
const CardExtractionSourceType = z.enum(['business_card', 'directory_listing']);
const CardVisionOutput = z.object({
  status: z.enum(['ok', 'no_card_detected']),
  sourceType: CardExtractionSourceType.default('business_card'),
  cards: z.array(z.object({
    index: z.number().int().min(1).max(50),
    firstName: z.string().min(1).max(100),
    lastName: z.string().min(1).max(100),
    email: z.string().max(320).default(''),
    phone: z.string().max(40).default(''),
    title: z.string().max(200).default(''),
    districtName: z.string().max(200).default(''),
    schoolName: z.string().max(200).default(''),
    extractionConfidence: confidence,
    boundingBox: z.object({ x: z.number().min(0).max(1), y: z.number().min(0).max(1), width: z.number().min(0).max(1), height: z.number().min(0).max(1) }).nullable().default(null),
  })).max(50),
}).refine((o) => o.status === 'no_card_detected' || o.cards.length > 0, { message: 'status=ok requires at least one card' });
const anthropicItem = $input.first().json;
const rawText = typeof anthropicItem.content === 'string' ? anthropicItem.content
  : Array.isArray(anthropicItem.content) ? anthropicItem.content.map((b) => (b && b.text) || '').join('')
  : typeof anthropicItem.text === 'string' ? anthropicItem.text
  : typeof anthropicItem.output === 'string' ? anthropicItem.output
  : JSON.stringify(anthropicItem);
let parsed;
try { parsed = extractJson(rawText); }
catch (err) { return [{ json: { success: false, error: 'no JSON object found in vision output: ' + err.message } }]; }
const result = CardVisionOutput.safeParse(parsed);
if (!result.success) {
  const issues = result.error.issues.map((i) => i.path.join('.') + ': ' + i.message).join('; ');
  return [{ json: { success: false, error: issues } }];
}
return [{ json: { success: true, data: result.data } }];

const data = $json.data;
const originalWidth = $('Compute Hash & Resize').item.json.originalWidth;
const originalHeight = $('Compute Hash & Resize').item.json.originalHeight;
const hash = $('Compute Hash & Resize').item.json.hash;
const storagePrefix = $('Compute Hash & Resize').item.json.storagePrefix;
const totalCards = data.cards.length;
const cards = data.cards.map((card) => {
  if (!card.boundingBox) { return Object.assign({}, card, { box: null, totalCards: totalCards, hash: hash, storagePrefix: storagePrefix }); }
  const bx = card.boundingBox;
  const pxX = bx.x * originalWidth;
  const pxY = bx.y * originalHeight;
  const pxW = bx.width * originalWidth;
  const pxH = bx.height * originalHeight;
  const padW = pxW * 0.15;
  const padH = pxH * 0.15;
  const left = Math.max(0, Math.round(pxX - padW));
  const top = Math.max(0, Math.round(pxY - padH));
  const right = Math.min(originalWidth, Math.round(pxX + pxW + padW));
  const bottom = Math.min(originalHeight, Math.round(pxY + pxH + padH));
  const box = { left: left, top: top, width: Math.max(1, right - left), height: Math.max(1, bottom - top) };
  return Object.assign({}, card, { box: box, totalCards: totalCards, hash: hash, storagePrefix: storagePrefix });
});
return [{ json: { sourceType: data.sourceType, cards: cards } }];

const cards = $json.cards;
const originalBinary = $input.item.binary ? $input.item.binary.original : undefined;
return cards.map((card) => ({ json: card, binary: card.box && originalBinary ? { original: originalBinary } : undefined }));

const sharp = require('sharp');
const originalBuffer = await this.helpers.getBinaryDataBuffer($itemIndex, 'original');
const box = $json.box;
const cropped = await sharp(originalBuffer).extract({ left: box.left, top: box.top, width: box.width, height: box.height }).toBuffer();
const cropFileName = $json.hash + '-crop-' + String($json.index).padStart(2, '0') + '.jpg';
const binaryData = await this.helpers.prepareBinaryData(cropped, cropFileName, 'image/jpeg');
return { json: Object.assign({}, $json, { cropFileName: cropFileName }), binary: { crop: binaryData } };

const sourceImageHash = $json.totalCards > 1 ? ($json.hash + '-' + String($json.index).padStart(2, '0')) : $json.hash;
const croppedImagePath = $json.cropFileName ? ($json.storagePrefix + '/' + $json.cropFileName) : null;
return { json: {
  firstName: $json.firstName, lastName: $json.lastName, email: $json.email, phone: $json.phone,
  title: $json.title, districtName: $json.districtName, schoolName: $json.schoolName,
  extractionConfidence: $json.extractionConfidence, sourceImageHash: sourceImageHash, croppedImagePath: croppedImagePath,
} };

const cards = $input.all().map((i) => i.json);
const sourceType = $('Compute Crop Boxes').item.json.sourceType;
return [{ json: { success: true, data: { sourceType: sourceType, cards: cards } } }];
